begin
 insert into public.course_exercises(id,version,title,author_draft,execution_definition,allowed_cells,sheets) values(data->'exercise'->>'id',data->'exercise'->>'version',data->'exercise'->>'title',data->'exercise',data->'definition',data->'manifest'->'allowedCells',data->'manifest'->'sheets') on conflict do nothing;
 for c in select * from jsonb_array_elements(data->'courses') loop
  if not exists(select 1 from public.courses where id=c->>'id') then perform app_private.upsert_course(c); end if;
 end loop;
end $seed$;
